import AppKit
import SwiftUI
import ClioCore

/// The Settings tab icons, one glyph per pane.
///
/// Drawn from their SVG path data rather than shipped as files: the package
/// has no resource bundle, and a template image drawn in code tints exactly
/// as an SF Symbol would, so the selected tab still lights up in the accent
/// colour. The source files are in Resources/Icon/Settings, and the strings
/// below are their `d` attributes, verbatim — paste a new export in and the
/// tab follows.
///
/// All seven are 24×24 with a one-point margin, and the same stroke weight,
/// which is what makes them read as a set where a mix of symbols did not.
@MainActor
enum SettingsIcon {
    static let general = image(General)
    static let model = image(Model)
    static let audio = image(Mic)
    static let transcription = image(Transcript)
    static let output = image(Output)
    static let feedback = image(Feedback)
    static let about = image(About)

    /// The box the paths are drawn in.
    private static let designSize: CGFloat = 24
    /// The image's own size. Nominal: the tab bar scales whatever it is
    /// given to a box of its own, about 32pt, and ignores this.
    private static let pointSize: CGFloat = 24
    /// How much of the image the 24-box takes up. Because the tab bar
    /// scales the image to its box, this is the only way to set the glyph's
    /// size on screen. At 0.7 the full-circle glyphs (About, Feedback) come
    /// out at the 21pt an SF Symbol has in the same bar; measured, not
    /// guessed, against a capture of the symbol version.
    private static let glyphScale: CGFloat = 0.7

    private static func image(_ data: String) -> Image {
        // The path is built inside the handler, from the string, so nothing
        // non-Sendable is captured; NSImage caches the drawing anyway.
        let image = NSImage(size: NSSize(width: pointSize, height: pointSize),
                            flipped: true) { rect in
            guard let context = NSGraphicsContext.current?.cgContext else { return false }
            let inset = rect.width * (1 - glyphScale) / 2
            context.translateBy(x: inset, y: inset)
            let scale = rect.width * glyphScale / designSize
            context.scaleBy(x: scale, y: scale)
            context.addPath(SVGPath.cgPath(data))
            context.setFillColor(.black)
            // Non-zero, the SVG default: the holes are wound the other way.
            context.fillPath()
            return true
        }
        image.isTemplate = true
        return Image(nsImage: image)
    }

